            return new ReportResult(id, zoneCode, "REPORTED", now);
        });

    confirm(long reportId, ConfirmRequest req):
        return idempotency.execute(req.requestId(), fp, ConfirmResult.class, () -> {
            PestReport r = reportRepo.findById(reportId).orElseThrow(notFound);
            if (!"REPORTED".equals(r.status())) throw unprocessable("上报已确认");
            Instant now = clock.instant();
            reportRepo.markConfirmed(reportId, now);
            long chainId = chainRepo.insert(r.zoneCode(), reportId, "TREATING", now);
            try { chainRepo.insertActive(r.zoneCode(), chainId); }
            catch (DuplicateKeyException e) { throw ApiException.conflict("同库区已存在进行中的处置链"); }
            Long evaluationId = maybeTriggerEvaluation(r, now);
            return new ConfirmResult(reportId, chainId, r.zoneCode(), "TREATING", evaluationId);
        });

    maybeTriggerEvaluation(report, now):
        windowStart = now.minus(90 days)
        Optional<PestReport> prev = reportRepo.findLatestUnconsumedAdjacentReport(zone, windowStart, now, report.id)
        if present:
            long evalId = reportRepo.insertEvaluation(report.zoneCode(), prev.zoneCode(), report.id(), now);
            reportRepo.markEvaluationConsumed(report.id());
            reportRepo.markEvaluationConsumed(prev.id());
            return evalId;
        return null;
}
